<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_login();$pdo=db();$leaders=$pdo->query("SELECT u.id,u.name,COALESCE(SUM(pt.points),0) points,COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE dp.donor_id=u.id AND dp.status='received'),0) items FROM users u LEFT JOIN points_transactions pt ON pt.user_id=u.id WHERE u.role='donor' AND u.is_active=1 GROUP BY u.id HAVING points>0 OR items>0 ORDER BY points DESC,items DESC,u.name LIMIT 25")->fetchAll();$pageTitle='Impact leaderboard';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="subnav"><a href="<?=e(url('donor/dashboard.php'))?>">Dashboard</a><a href="<?=e(url('donor/passport.php'))?>">Passport</a><a href="<?=e(url('donor/achievements.php'))?>">Achievements</a><a class="is-active" href="<?=e(url('donor/leaderboard.php'))?>">Leaderboard</a></div><div class="welcome-row"><div><span class="eyebrow">Community-powered</span><h1>Impact leaderboard</h1><p>Ranked by verified impact points—not unconfirmed pledges.</p></div></div><div class="panel" style="max-width:760px;margin:auto"><?php if(!$leaders):?><div class="empty"><span class="empty-icon">★</span>The first completed donation will start the leaderboard.</div><?php else:foreach($leaders as $i=>$leader):?><div class="leaderboard-row"><span class="rank">#<?=$i+1?></span><div><strong><?=e($leader['name'])?></strong><br><small class="muted"><?=e($leader['items'])?> confirmed item(s)</small></div><strong><?=number_format((int)$leader['points'])?> pts</strong></div><?php endforeach;endif;?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
